	private record NativeInput(Value value, long id, ValueStore.ReadSnapshot snapshot) {
	}

	private static final class ProbeValues extends ValueStore {
		final ThreadLocal<ReadSnapshot> currentPin = new ThreadLocal<>();
		final List<NativeInput> inputs = new ArrayList<>();
		boolean plannerCall;

		ProbeValues(File directory, StoreProperties properties, LmdbStoreConfig config) throws IOException {
			super(directory, properties, config);
		}

		@Override
		SailClosable pinQueryPlanningReads(ReadSnapshot snapshot) {
			SailClosable delegate = super.pinQueryPlanningReads(snapshot);
			ReadSnapshot previous = currentPin.get();
			currentPin.set(snapshot);
			return () -> {
				try {
					delegate.close();
				} finally {
					if (previous == null) {
						currentPin.remove();
					} else {
						currentPin.set(previous);
					}
				}
			};
		}

		@Override
		long getStatementId(ReadSnapshot snapshot, Value value) throws IOException {
			long id = super.getStatementId(snapshot, value);
			if (plannerCall && StackWalker.getInstance()
					.walk(frames -> frames
							.anyMatch(frame -> frame.getClassName().equals(LmdbPackedCostModel.class.getName())
									&& frame.getMethodName().equals("mappedLeafEstimate")))) {
				inputs.add(new NativeInput(value, id, snapshot));
			}
			return id;
		}
	}

	private static final class ProbeStore extends LmdbStore {
		ProbeValues values;
		TripleStore triples;

		ProbeStore(File directory, boolean posc) {
			super(directory, new LmdbStoreConfig(posc ? "spoc,ospc,psoc,posc" : "spoc,ospc,psoc")
					.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches,
					(d, p, c) -> {
						values = new ProbeValues(d, p, c);
						return values;
					},
					(d, p, c, v) -> {
						triples = new TripleStore(d, p, c, v);
						return triples;
					});
		}
	}
